def bound(self, nums: List[int], target: int, strict: bool) -> int:
    left, right = 0, len(nums)
    while left < right:
        mid = (left + right) // 2
        if nums[mid] < target or (strict and nums[mid] == target):
            left = mid + 1
        else:
            right = mid
    return left

