def meeting_point(self, head: Optional[ListNode]) -> Optional[ListNode]:
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            return slow
    return None

def detectCycle(self, head: Optional[ListNode]) -> Optional[ListNode]:
    meet = self.meeting_point(head)
    if meet is None:
        return None
    start = head
    while start is not meet:
        start = start.next
        meet = meet.next
    return start
